package template

import (
	"fmt"
	"path/filepath"
)

// The wiring vocabulary: the parameter names block templates record in
// their scaffold values and later commands (sys create/update, deploy,
// prompt suggestions) read back. They are CLI-owned convention, not
// manifest schema — a template that names its parameters otherwise simply
// gets no assembly or suggestions. One home so a vocabulary change has
// one diff, not a scavenger hunt.
const (
	KeyAppID        = "appId"
	KeyTopic        = "topic"
	KeyContract     = "contract"
	KeyPubsub       = "pubsub"
	KeyPort         = "port"
	KeyFromPort     = "fromPort"
	KeyToPort       = "toPort"
	KeyName         = "name"
	KeyOrganization = "organization"
	KeyProjectName  = "projectName"
	KeySystemClass  = "systemClass"

	// DefaultPubsub is the pub/sub component a record belongs to when it
	// predates the pubsub value being recorded.
	DefaultPubsub = "pubsub"
)

// RecordValue reads key from a scaffold record's values as a non-empty
// string. Missing, mistyped, and empty values are errors naming the
// record, so the user knows which project to fix. It is the strict
// regime: callers validating a workspace (system assembly) use it;
// callers offering suggestions use SoftValue instead.
func RecordValue(e ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// RecordValueDefault is RecordValue with a fallback for records that
// predate the value being recorded. Only a missing key falls back; a
// present but mistyped or empty value is still an error — a record that
// names the key must say something meaningful.
func RecordValueDefault(e ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return RecordValue(e, key)
}

// SoftValue reads key from a values map as a non-empty string, reporting
// false for missing, mistyped, or empty values. It is the lenient regime:
// suggestion aids and best-effort joins skip such records rather than
// failing an operation the records themselves would still allow.
func SoftValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

package template

import (
	"path/filepath"
	"testing"
)

func wiringEntry(values map[string]any) ScaffoldEntry {
	return ScaffoldEntry{Path: "order-extractor", Scaffold: Scaffold{Values: values}}
}

func TestRecordValue(t *testing.T) {
	recordPath := filepath.ToSlash(filepath.Join("order-extractor", filepath.FromSlash(ScaffoldRelPath)))

	t.Run("missing, mistyped, and empty name the record", func(t *testing.T) {
		cases := []struct {
			values  map[string]any
			wantErr string
		}{
			{map[string]any{}, recordPath + ": values.topic is missing"},
			{map[string]any{"topic": float64(7)}, recordPath + ": values.topic has type float64, expected string"},
			{map[string]any{"topic": ""}, recordPath + ": values.topic is empty"},
		}
		for _, tc := range cases {
			if _, err := RecordValue(wiringEntry(tc.values), KeyTopic); err == nil || filepath.ToSlash(err.Error()) != tc.wantErr {
				t.Errorf("RecordValue(%v) err = %v, want %q", tc.values, err, tc.wantErr)
			}
		}
	})

	t.Run("present value returns", func(t *testing.T) {
		got, err := RecordValue(wiringEntry(map[string]any{"topic": "orders"}), KeyTopic)
		if err != nil || got != "orders" {
			t.Errorf("RecordValue = %q, %v; want orders, nil", got, err)
		}
	})
}

func TestRecordValueDefault(t *testing.T) {
	t.Run("missing falls back", func(t *testing.T) {
		got, err := RecordValueDefault(wiringEntry(map[string]any{}), KeyPubsub, DefaultPubsub)
		if err != nil || got != DefaultPubsub {
			t.Errorf("RecordValueDefault = %q, %v; want %q, nil", got, err, DefaultPubsub)
		}
	})

	t.Run("present but mistyped or empty is an error, not the fallback", func(t *testing.T) {
		for _, values := range []map[string]any{{"pubsub": 7}, {"pubsub": ""}} {
			if _, err := RecordValueDefault(wiringEntry(values), KeyPubsub, DefaultPubsub); err == nil {
				t.Errorf("RecordValueDefault(%v) = nil error, want a record error", values)
			}
		}
	})
}

func TestSoftValue(t *testing.T) {
	cases := []struct {
		values map[string]any
		want   string
		ok     bool
	}{
		{map[string]any{"topic": "orders"}, "orders", true},
		{map[string]any{}, "", false},
		{map[string]any{"topic": ""}, "", false},
		{map[string]any{"topic": 7}, "", false},
	}
	for _, tc := range cases {
		got, ok := SoftValue(tc.values, KeyTopic)
		if got != tc.want || ok != tc.ok {
			t.Errorf("SoftValue(%v) = %q, %v; want %q, %v", tc.values, got, ok, tc.want, tc.ok)
		}
	}
}

